def two_array_two_sum(sorted_arr, unsorted_arr):

  def binary_search(arr, target):

    def is_before(i):
      return arr[i] < target

    l, r = 0, len(arr) - 1
    if arr[l] > target or arr[r] < target:
      return -1
    if arr[l] == target:
      return l

    while r - l > 1:
      mid = (l + r) // 2
      if is_before(mid):
        l = mid
      else:
        r = mid

    if arr[r] == target:
      return r
    return -1

  for i, val in enumerate(unsorted_arr):
    idx = binary_search(sorted_arr, -val)
    if idx != -1:
      return [idx, i]
  return [-1, -1]

